from pathlib import Path
s=Path('astra-remaining-improvements/stage/b415b13a50ee');p=s/'server.js';t=p.read_text(encoding='utf-8').replace("import { resolve, extname, sep } from 'node:path';", "import { resolve, extname, sep, dirname } from 'node:path';\nimport { fileURLToPath } from 'node:url';").replace("const root = resolve('extension');", "const root = resolve(dirname(fileURLToPath(import.meta.url)), 'extension');").replace("if (error.code === 'EADDRINUSE')", "if (error.code === 'EADDRINUSE' && process.env.INTERLUDE_STRICT_PORT !== '1')");p.write_text(t,encoding='utf-8')
p=s/'tests/model.test.js';p.write_text(r'''
import test from 'node:test';
import assert from 'node:assert/strict';
import { normalize, parsePreview, applyMessage, validateSettings } from '../extension/model.js';
const preset = {id:'water',title:'Water break',message:'Stand up and drink water.'};
const change = (snapshot,settings,expectedRevision=snapshot.revision)=>applyMessage(snapshot,{type:'settings',settings,expectedRevision});
test('legacy snapshot gains revision and empty library without mutation',()=>{const old={settings:{focus:25}},before=JSON.stringify(old),result=normalize(old);assert.equal(result.revision,0);assert.equal(result.state.total,25*60000);assert.deepEqual(result.presets,[]);assert.equal(JSON.stringify(old),before);});
test('malformed preview JSON is rejected instead of replacing it with defaults',()=>{assert.throws(()=>parsePreview('{broken'),/unreadable/);assert.throws(()=>parsePreview('null'),/Invalid/);});
test('invalid persisted timer values are rejected',()=>{for(const patch of [{phase:'other'},{running:true,deadline:null},{remaining:-1},{total:0},{completed:1.5}]){const snapshot=normalize();Object.assign(snapshot.state,patch);assert.throws(()=>normalize(snapshot),/Invalid/);}});
test('settings validate booleans durations artwork and unknown keys',()=>{for(const patch of [{focus:0},{breakMinutes:61},{shuffle:'false'},{art:'remote'},{customArt:'https://example.com/image'},{unexpected:true}])assert.throws(()=>validateSettings(patch),/Invalid/);});
test('custom art requires bounded local data and a matching selection',()=>{assert.throws(()=>validateSettings({art:'custom'}),/missing/);assert.equal(validateSettings({art:'custom',customArt:'data:image/jpeg;base64,YQ=='}).art,'custom');assert.throws(()=>validateSettings({customName:'x'.repeat(71)}),/name/);});
test('partial settings change preserves all unrelated values',()=>{let snapshot=normalize();snapshot=change(snapshot,{focus:25});const updated=change(snapshot,{message:'A new reminder'});assert.equal(updated.settings.focus,25);assert.equal(updated.settings.message,'A new reminder');assert.equal(updated.revision,2);});
test('stale settings revision cannot overwrite another accepted edit',()=>{const old=normalize(),winner=change(old,{message:'Winner'});assert.throws(()=>change(winner,{message:'Stale'},old.revision),/changed elsewhere/);assert.equal(winner.settings.message,'Winner');});
test('settings changes reset idle focus but do not rewrite a running deadline',()=>{let snapshot=normalize();snapshot=change(snapshot,{focus:25});assert.equal(snapshot.state.total,1500000);snapshot=applyMessage(snapshot,{type:'command',command:'start'},1000);const next=change(snapshot,{focus:50});assert.equal(next.state.deadline,snapshot.state.deadline);assert.equal(next.settings.focus,50);});
test('timer commands preserve settings revision and library',()=>{let snapshot=applyMessage(normalize(),{type:'preset',action:'create',preset,expectedRevision:0});const next=applyMessage(snapshot,{type:'command',command:'start'},1000);assert.equal(next.revision,1);assert.deepEqual(next.presets,[preset]);});
test('saved message create uses stable identity and detached values',()=>{const next=applyMessage(normalize(),{type:'preset',action:'create',preset,expectedRevision:0});assert.deepEqual(next.presets,[preset]);next.presets[0].title='Changed';assert.equal(preset.title,'Water break');});
test('duplicate saved-message create fails without changing the library',()=>{const next=applyMessage(normalize(),{type:'preset',action:'create',preset,expectedRevision:0});assert.throws(()=>applyMessage(next,{type:'preset',action:'create',preset,expectedRevision:1}),/already exists/);assert.equal(next.presets.length,1);});
test('saved message update requires existence and unchanged identity',()=>{const next=applyMessage(normalize(),{type:'preset',action:'create',preset,expectedRevision:0});const updated=applyMessage(next,{type:'preset',action:'update',id:preset.id,preset:{...preset,message:'Updated'},expectedRevision:1});assert.equal(updated.presets[0].message,'Updated');assert.throws(()=>applyMessage(next,{type:'preset',action:'update',id:'missing',preset,expectedRevision:1}),/identity/);});
test('delete removes only the saved copy and leaves active reminder unchanged',()=>{let snapshot=normalize();const active=snapshot.settings.message;snapshot=applyMessage(snapshot,{type:'preset',action:'create',preset,expectedRevision:0});const next=applyMessage(snapshot,{type:'preset',action:'delete',id:preset.id,expectedRevision:1});assert.deepEqual(next.presets,[]);assert.equal(next.settings.message,active);assert.throws(()=>applyMessage(next,{type:'preset',action:'delete',id:preset.id,expectedRevision:2}),/not found/);});
test('stale library edits are rejected after settings change',()=>{const winner=change(normalize(),{message:'Changed'});assert.throws(()=>applyMessage(winner,{type:'preset',action:'create',preset,expectedRevision:0}),/changed elsewhere/);});
test('library text lengths blank input and maximum count are bounded',()=>{for(const value of [{...preset,title:' '},{...preset,message:''},{...preset,message:'x'.repeat(501)}])assert.throws(()=>applyMessage(normalize(),{type:'preset',action:'create',preset:value,expectedRevision:0}),/Invalid/);const snapshot=normalize();snapshot.presets=Array.from({length:30},(_,i)=>({...preset,id:'p'+i}));assert.throws(()=>applyMessage(snapshot,{type:'preset',action:'create',preset,expectedRevision:0}),/30/);});
test('stored duplicate library IDs cannot be loaded',()=>{const snapshot=normalize();snapshot.presets=[preset,preset];assert.throws(()=>normalize(snapshot),/duplicate/);});
test('invalid commands extra fields and clock values are rejected',()=>{assert.throws(()=>applyMessage(normalize(),{type:'unknown'}),/Unknown/);assert.throws(()=>applyMessage(normalize(),{type:'command',command:'start',settings:{focus:1}}),/fields/);assert.throws(()=>applyMessage(normalize(),{type:'command',command:'start'},NaN),/clock/);});
test('revision overflow and empty patches cannot silently succeed',()=>{const snapshot=normalize();snapshot.revision=Number.MAX_SAFE_INTEGER;assert.throws(()=>change(snapshot,{message:'x'}),/exhausted/);assert.throws(()=>change(normalize(),{}),/empty/);});
'''.strip()+'\n',encoding='utf-8');print('18 shared-model regression cases written')
